const countOut = document.getElementById('count');
const stepInput = document.getElementById('step');
const decrement = document.getElementById('decrement');
const increment = document.getElementById('increment');
const reset = document.getElementById('reset');

let count = 0;

function step() {
  return Number(stepInput.value) || 1;
}

function render() {
  countOut.textContent = String(count);
  decrement.disabled = count === 0;
}

increment.addEventListener('click', () => {
  count += step();
  render();
});

decrement.addEventListener('click', () => {
  count -= step();
  render();
});

reset.addEventListener('click', () => {
  count = 0;
});

render();

files.referenceContent:
const countOut = document.getElementById('count');
const stepInput = document.getElementById('step');
const decrement = document.getElementById('decrement');
const increment = document.getElementById('increment');
const reset = document.getElementById('reset');

let count = 0;

function step() {
  return Math.max(1, Number(stepInput.value) || 1);
}

function render() {
  countOut.textContent = String(count);
  decrement.disabled = count < step();
}

increment.addEventListener('click', () => {
  count += step();
  render();
});

decrement.addEventListener('click', () => {
  count = Math.max(0, count - step());
  render();
});

reset.addEventListener('click', () => {
  count = 0;
  render();
});

stepInput.addEventListener('input', render);
render();
